INSERT INTO `script` VALUES (1,NULL,_binary '\0','나 대학교 다닐 때 시험기간마다 도서관 3층 64번 자리에만 앉았음.',1,1,NULL),(2,NULL,_binary '\0','창가 자리라서 햇빛도 잘 들고 에어컨 바람도 안 와서 딱 좋았거든.',2,1,NULL),(3,NULL,_binary '\0','근데 어느 날부터 그 자리에 항상 먼저 와있는 애가 있는 거임.',3,1,NULL),(4,NULL,_binary '\0','65번 자리에 앉아서 책 읽고 있더라고.',4,1,NULL),(5,NULL,_binary '\0','처음엔 짜증났음. 내 자리 옆에 왜 앉냐고.',5,1,NULL),(6,NULL,_binary '\0','그런데 그 애가 책상에 A4 용지 하나를 올려두고 가는 거야.',6,1,NULL),(7,NULL,_binary '\0','거기에 연필로 \'64번 자리 비워둘게요\' 이렇게 적어둔 거임.',7,1,NULL),(8,NULL,_binary '\0','뭔가 이상하다 싶었는데 일단 고맙긴 해서 그냥 앉았음.',8,1,NULL),(9,NULL,_binary '\0','다음 날도 똑같더라고. 65번에 그 애 있고, 64번엔 쪽지.',9,1,NULL),(10,NULL,_binary '\0','근데 이번엔 \'오늘 비 온대요. 우산 챙기세요\' 이렇게 적혀있음.',10,1,NULL),(11,NULL,_binary '\0','이게 뭐지? 싶어서 슬쩍 옆을 봤는데 그 애가 책에 집중하고 있어서 말 걸기 애매했음.',11,1,NULL),(12,NULL,_binary '\0','그날 정말 비 왔음. 우산 안 가져갔으면 비 맞을 뻔했어.',12,1,NULL),(13,NULL,_binary '\0','그 다음 날부터 호기심이 생기기 시작함.',13,1,NULL),(14,NULL,_binary '\0','쪽지 내용이 매일 달라지거든.',14,1,NULL),(15,NULL,_binary '\0','\'오늘 학식 돈까스 맛없다고 하네요\', \'3층 화장실 휴지 떨어졌어요\'',15,1,NULL),(16,NULL,_binary '\0','이런 식으로 은근 유용한 정보들이었음.',16,1,NULL),(17,NULL,_binary '\0','한 달 정도 지났을 때 그 애 얼굴을 제대로 본 적이 없다는 걸 깨달았어.',17,1,NULL),(18,NULL,_binary '\0','항상 내가 올 때는 이미 책 보고 있고, 내가 자리 뜰 때는 아직 앉아있고.',18,1,NULL),(19,NULL,_binary '\0','궁금해서 일부러 일찍 가봤는데도 이미 앉아있더라.',19,1,NULL),(20,NULL,_binary '\0','도대체 몇 시에 오는 거야?',20,1,NULL),(21,NULL,_binary '\0','어느 날 쪽지에 \'시험 잘 보세요. 항상 열심히 하시는 모습 멋있어요\' 이렇게 적혀있는 거임.',21,1,NULL),(22,NULL,_binary '\0','이때 뭔가 심장이 두근거렸어.',22,1,NULL),(23,NULL,_binary '\0','그래서 용기내서 쪽지 밑에 작은 글씨로 \'고마워요\' 이렇게 적어뒀음.',23,1,NULL),(24,NULL,_binary '\0','다음 날 가보니까 내 글씨 옆에 이모티콘 하나 그려져 있었어.',24,1,NULL),(25,NULL,_binary '\0','웃는 얼굴이었는데 되게 귀엽게 그렸더라고.',25,1,NULL),(26,NULL,_binary '\0','그날부터 우리 쪽지 주고받기 시작함.',26,1,NULL),(27,NULL,_binary '\0','근데 진짜 대화는 안 해. 계속 쪽지로만.',27,1,NULL),(28,NULL,_binary '\0','\'오늘 뭐 공부해요?\' \'전공이 뭐예요?\' 이런 것들.',28,1,NULL),(29,NULL,_binary '\0','알고 보니까 그 애는 미술과였음.',29,1,NULL),(30,NULL,_binary '\0','그래서 쪽지에 작은 그림도 그려주고 글씨도 예쁘게 썼던 거더라.',30,1,NULL),(31,NULL,_binary '\0','나는 경영학과라고 했더니 다음 날 쪽지에 작은 계산기 그림이 그려져 있었어 ㅋㅋㅋ',31,1,NULL),(32,NULL,_binary '\0','시험이 끝나고 방학이 되니까 도서관에 갈 일이 없어짐.',32,1,NULL),(33,NULL,_binary '\0','근데 그 애가 궁금한 거야.',33,1,NULL),(34,NULL,_binary '\0','그래서 개강하고 바로 도서관 갔는데 65번 자리가 비어있더라.',34,1,NULL),(35,NULL,_binary '\0','64번에 쪽지도 없고.',35,1,NULL),(36,NULL,_binary '\0','혹시 시간표가 바뀐 건가 싶어서 계속 다녀봤는데 한 주 내내 없었어.',36,1,NULL),(37,NULL,_binary '\0','그러다가 일주일 뒤에 64번 자리에 쪽지 하나가 놓여있는 거 발견함.',37,1,NULL),(38,NULL,_binary '\0','\'미안해요. 교환학생으로 가게 됐어요. 1년 후에 돌아와요\'',38,1,NULL),(39,NULL,_binary '\0','그 밑에 작은 비행기 그림하나 그려져 있었음.',39,1,NULL),(40,NULL,_binary '\0','진짜 허무했어. 얼굴도 제대로 못 본 채로 헤어진 거잖아.',40,1,NULL),(41,NULL,_binary '\0','그 뒤로 도서관 가면 65번 자리만 계속 쳐다봤어.',41,1,NULL),(42,NULL,_binary '\0','1년이 지나고 그 애가 돌아왔는지 확인하러 갔는데 또 없더라.',42,1,NULL),(43,NULL,_binary '\0','근데 며칠 뒤에 도서관 앞 게시판에 전시회 포스터 하나가 붙어있는 거 봤어.',43,1,NULL),(44,NULL,_binary '\0','미술과 졸업전시회였는데 포스터 한쪽 모서리에 작은 글씨로 \'64\'라고 적혀있었음.',44,1,NULL),(45,NULL,_binary '\0','그 글씨체가 쪽지랑 똑같았어.',45,1,NULL),(46,NULL,_binary '\0','전시회 가봤는데 작품 중에 도서관 그림이 하나 있더라고.',46,1,NULL),(47,NULL,_binary '\0','3층 창가 자리를 그린 건데 64번 책상 위에 작은 쪽지들이 쌓여있는 그림이었어.',47,1,NULL),(48,NULL,_binary '\0','그림 제목이 \'말 못한 인사\'였음.',48,1,NULL),(49,NULL,_binary '\0','그때 옆에서 누군가 말을 거는 거야. \'그 자리 아세요?\'',49,1,NULL),(50,NULL,_binary '\0','돌아보니까 익숙한데 낯선 얼굴이었어.',50,1,NULL),(51,NULL,_binary '\0','1년 동안 매일 옆에 앉았던 그 애였음.',51,1,NULL),(52,NULL,_binary '\0','\'1년 내내 인사하고 싶었는데 용기가 안 났어요\'라고 하더라.',52,1,NULL),(53,NULL,_binary '\0','나도 똑같았다고 했어.',53,1,NULL),(54,NULL,_binary '\0','그 애가 웃으면서 \'이제 쪽지 말고 진짜 대화할 수 있을까요?\' 이러는데 목소리가 떨리고 있었음.',54,1,NULL),(55,NULL,_binary '\0','나도 떨렸어.',55,1,NULL),(56,NULL,_binary '\0','지금도 그 애랑 만나고 있음.',56,1,NULL),(57,NULL,_binary '\0','아직도 가끔 쪽지로 대화해 ㅋㅋㅋ',57,1,NULL),(58,NULL,_binary '\0','연우는 동네 서점에서 일했다.',1,2,NULL),(59,NULL,_binary '\0','작은 서점이라 손님이 많지 않았다.',2,2,NULL),(60,NULL,_binary '\0','그런데 한 명만 매일 왔다.',3,2,NULL),(61,NULL,_binary '\0','학교 끝나고 오는 고등학생.',4,2,NULL),(62,NULL,_bi