0','이거 내가 먼저 물어봐도 되는 거 맞냐고.',41,8,NULL),(468,NULL,_binary '\0','근데 그냥 초보 다치는 거 못 보는 착한 사람이면 나 거기 다시는 못 갈 것 같은데.',42,8,NULL),(469,NULL,_binary '\0','아직도 모르겠음.',43,8,NULL),(470,NULL,_binary '\0','하윤은 김밥이 지겨웠다.',1,9,NULL),(471,NULL,_binary '\0','3년째였으니까.',2,9,NULL),(472,NULL,_binary '\0','중3 겨울부터 고3 가을까지, 엄마는 하루도 빠짐없이 새벽에 김밥을 쌌다.',3,9,NULL),(473,NULL,_binary '\0','참기름 냄새로 잠이 깨는 아침.',4,9,NULL),(474,NULL,_binary '\0','\"다른 거 좀 싸주면 안 돼?\"',5,9,NULL),(475,NULL,_binary '\0','엄마는 대답 대신 웃기만 했는데.',6,9,NULL),(476,NULL,_binary '\0','\"김밥이 제일 안 상해.\"',7,9,NULL),(477,NULL,_binary '\0','그 말만 3년.',8,9,NULL),(478,NULL,_binary '\0','그런데 9월쯤부터 맛이 조금씩 어긋나기 시작했다.',9,9,NULL),(479,NULL,_binary '\0','처음엔 단무지가 없었다.',10,9,NULL),(480,NULL,_binary '\0','다음 날엔 단무지가 두 줄씩 들어가 있었고.',11,9,NULL),(481,NULL,_binary '\0','그 주 목요일엔 밥이 너무 짜서 한 입 먹고 물을 세 번 마셨다.',12,9,NULL),(482,NULL,_binary '\0','짜증이 확 올라왔다.',13,9,NULL),(483,NULL,_binary '\0','쉬는 시간에 전화를 걸었다.',14,9,NULL),(484,NULL,_binary '\0','\"엄마, 오늘 김밥 왜 이래.\"',15,9,NULL),(485,NULL,_binary '\0','\"응? 이상해? 미안해, 다시 쌀게.\"',16,9,NULL),(486,NULL,_binary '\0','다시 쌀게라니.',17,9,NULL),(487,NULL,_binary '\0','점심시간이 끝나가는 중이었는데.',18,9,NULL),(488,NULL,_binary '\0','하윤은 그냥 끊었다.',19,9,NULL),(489,NULL,_binary '\0','10월 둘째 주 화요일.',20,9,NULL),(490,NULL,_binary '\0','야자가 있는 날인데 교문 앞에 엄마가 서 있었다.',21,9,NULL),(491,NULL,_binary '\0','장바구니를 든 채로.',22,9,NULL),(492,NULL,_binary '\0','\"너 오늘 일찍 끝난다며.\"',23,9,NULL),(493,NULL,_binary '\0','그런 말을 한 적이 없었다.',24,9,NULL),(494,NULL,_binary '\0','\"엄마, 오늘 화요일이야.\"',25,9,NULL),(495,NULL,_binary '\0','엄마가 잠깐 멈칫하더니 웃었다.',26,9,NULL),(496,NULL,_binary '\0','\"아, 맞다. 엄마가 요일을 헷갈렸네.\"',27,9,NULL),(497,NULL,_binary '\0','그 웃음이 이상하게 오래 남았다.',28,9,NULL),(498,NULL,_binary '\0','며칠 뒤, 도시락 가방이 유난히 무거웠다.',29,9,NULL),(499,NULL,_binary '\0','열어보니 김밥이 여섯 줄.',30,9,NULL),(500,NULL,_binary '\0','평소엔 두 줄이었다.',31,9,NULL),(501,NULL,_binary '\0','친구들이 좋다고 달려들어서 순식간에 다 없어졌는데.',32,9,NULL),(502,NULL,_binary '\0','하윤만 웃지 못했다.',33,9,NULL),(503,NULL,_binary '\0','그날 밤, 물을 꺼내려고 부엌에 갔다가 엄마 앞치마가 의자에 걸려 있는 걸 봤다.',34,9,NULL),(504,NULL,_binary '\0','주머니가 불룩했다.',35,9,NULL),(505,NULL,_binary '\0','손바닥만 한 수첩.',36,9,NULL),(506,NULL,_binary '\0','펼쳐 보고 손이 멈췄다.',37,9,NULL),(507,NULL,_binary '\0','\"하윤이 김밥 두 줄. 참기름 조금. 단무지 꼭.\"',38,9,NULL),(508,NULL,_binary '\0','다음 장에도 같은 문장.',39,9,NULL),(509,NULL,_binary '\0','그다음 장에도.',40,9,NULL),(510,NULL,_binary '\0','날짜만 바뀐 채로 스무 장 넘게 똑같은 글씨가 이어졌다.',41,9,NULL),(511,NULL,_binary '\0','뒤로 갈수록 글씨가 커지고 줄이 삐뚤어져 있었다.',42,9,NULL),(512,NULL,_binary '\0','맨 마지막 장 사이에 종이 한 장이 끼워져 있었는데.',43,9,NULL),(513,NULL,_binary '\0','대학병원 신경과 진료 카드.',44,9,NULL),(514,NULL,_binary '\0','석 달 전 날짜.',45,9,NULL),(515,NULL,_binary '\0','다음 예약 칸은 비어 있었다.',46,9,NULL),(516,NULL,_binary '\0','거짓말.',47,9,NULL),(517,NULL,_binary '\0','하윤은 수첩을 원래대로 접어서 주머니에 다시 넣었다.',48,9,NULL),(518,NULL,_binary '\0','그리고 방에 들어가 불을 끄고 한참을 누워 있었다.',49,9,NULL),(519,NULL,_binary '\0','다음 날 새벽 다섯 시 사십 분, 부엌에 불이 켜졌다.',50,9,NULL),(520,NULL,_binary '\0','하윤이 문을 열고 나갔다.',51,9,NULL),(521,NULL,_binary '\0','엄마가 김발 앞에서 놀란 얼굴로 돌아봤다.',52,9,NULL),(522,NULL,_binary '\0','\"왜 벌써 일어났어.\"',53,9,NULL),(523,NULL,_binary '\0','\"나도 배울래.\"',54,9,NULL),(524,NULL,_binary '\0','\"너 김밥 싫어하잖아.\"',55,9,NULL),(525,NULL,_binary '\0','\"아니.\"',56,9,NULL),(526,NULL,_binary '\0','\"좋아해.\"',57,9,NULL),(527,NULL,_binary '\0','엄마가 잠깐 하윤을 보더니, 단무지 접시를 옆으로 밀어줬다.',58,9,NULL),(528,NULL,_binary '\0','손끝이 조금 떨렸다.',59,9,NULL),(529,NULL,_binary '\0','하윤은 수첩 얘기를 꺼내지 않았다.',60,9,NULL),(530,NULL,_binary '\0','대신 학교 앞 문구점에서 똑같은 수첩을 하나 샀다.',61,9,NULL),(531,NULL,_binary '\0','첫 장에 이렇게 적었다.',62,9,NULL),(532,NULL,_binary '\0','\"엄마 김밥. 참기름 조금. 단무지 꼭.\"',63,9,NULL),(533,NULL,_binary '\0','이건 자기가 기억하기로 했다.',64,9,NULL);
