--
-- Table structure for table `quiz_content`
--

DROP TABLE IF EXISTS `quiz_content`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quiz_content` (
  `quiz_content_id` bigint NOT NULL AUTO_INCREMENT,
  `quiz_id` bigint NOT NULL,
  `lang_code` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `question` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `options` json DEFAULT NULL,
  `correct_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `explanation` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `hint` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `acceptable_answers` json DEFAULT NULL,
  PRIMARY KEY (`quiz_content_id`),
  UNIQUE KEY `uq_quiz_lang` (`quiz_id`,`lang_code`),
  CONSTRAINT `quiz_content_ibfk_1` FOREIGN KEY (`quiz_id`) REFERENCES `quiz_detail` (`quiz_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20613 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

